import java.io.*;

public class Main {
    private static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        int nextInt() throws IOException {
            while (ptr < len && buffer[ptr] <= ' ') ptr++;
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                while (ptr < len && buffer[ptr] <= ' ') ptr++;
            }
            int sign = 1;
            if (buffer[ptr] == '-') {
                sign = -1;
                ptr++;
            }
            int value = 0;
            while (ptr < len && buffer[ptr] > ' ') {
                value = value * 10 + buffer[ptr++] - '0';
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int rows = fs.nextInt();
        int cols = fs.nextInt();

        int[] previous = new int[cols];
        for (int j = 0; j < cols; j++) previous[j] = fs.nextInt();

        int width = cols - 1;
        int[] heights = new int[width];
        int[] stack = new int[width + 1];
        long answer = Math.max(rows, cols);

        for (int i = 1; i < rows; i++) {
            int[] current = new int[cols];
            for (int j = 0; j < cols; j++) current[j] = fs.nextInt();

            for (int j = 0; j < width; j++) {
                long delta = (long) previous[j] + current[j + 1]
                        - previous[j + 1] - current[j];
                heights[j] = delta <= 0 ? heights[j] + 1 : 0;
            }

            int top = -1;
            for (int j = 0; j <= width; j++) {
                int currentHeight = j == width ? 0 : heights[j];
                while (top >= 0 && heights[stack[top]] > currentHeight) {
                    int height = heights[stack[top--]];
                    if (height > 0) {
                        int left = top >= 0 ? stack[top] + 1 : 0;
                        int rectangleWidth = j - left;
                        long area = (long) (height + 1) * (rectangleWidth + 1);
                        answer = Math.max(answer, area);
                    }
                }
                if (j < width) stack[++top] = j;
            }

            previous = current;
        }

        System.out.println(answer);
    }
}
